from pathlib import Path
import subprocess,json,hashlib,statistics,random,fcntl
p=Path(__file__).parent;variants=['baseline','limit1','exclusive','combined'];configs={'gcc_native':['/usr/bin/g++','-march=native'],'clang_standard':['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']};rng=random.Random(731824);rows=[];builds=[]
for conf,cc in configs.items():
 for op in [0,1]:
  for v in variants:
   exe=p/f'{conf}_{v}_{op}';cmd=['taskset','-c','0',*cc,'-std=c++23','-O2',f'-DSOURCE="{p/(v+".hpp")}"',f'-DOP={op}',str(p/'api.cpp'),'-o',str(exe)];o=subprocess.run(cmd,capture_output=True,text=True);assert o.returncode==0,o.stderr;builds.append(dict(configuration=conf,op=op,variant=v,cmd=cmd,source_sha256=hashlib.sha256((p/(v+'.hpp')).read_bytes()).hexdigest(),stderr=o.stderr))
with open('/tmp/sirkit_performance_cpu4.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for conf in configs:
  for n in [31,1048576]:
   for op in [0,1]:
    for mode in ([0,1,2,3,8,9,10,11,12]if op==0 else[0,1,2,3,8,9]):
     vals={v:[]for v in variants};checks={v:[]for v in variants}
     for rep in range(7):
      order=variants.copy();rng.shuffle(order)
      for v in order:
       o=subprocess.run(['taskset','-c','4',str(p/f'{conf}_{v}_{op}'),str(n),str(mode),'32768'],capture_output=True,text=True);assert o.returncode==0,o.stderr;ns,checksum=o.stdout.split();vals[v].append(float(ns));checks[v].append(checksum)
      assert len({checks[v][-1]for v in variants})==1,(conf,n,op,mode,checks)
     med={v:statistics.median(x)for v,x in vals.items()};row=dict(configuration=conf,n=n,op=op,mode=mode,raw=vals,median_ns=med,ratio={v:x/med['baseline']for v,x in med.items()});rows.append(row);(p/'results.json').write_text(json.dumps(dict(builds=builds,rows=rows),indent=2));print(conf,n,op,mode,{v:round(x,3)for v,x in row['ratio'].items()},flush=True)

